"use client"

import * as React from "react"
import { cn } from "@/lib/utils"
import { useOverflowX } from "@/lib/use-overflow-x"

function Table({ className, ...props }: React.ComponentProps<"table">) {
  const containerRef = React.useRef<HTMLDivElement>(null)
  // A table wider than its container scrolls sideways: then the container takes
  // focus so keyboard users can scroll it with the arrow keys.
  const scrolls = useOverflowX(containerRef)
  return (
    <div
      ref={containerRef}
      data-slot="table-container"
      tabIndex={scrolls ? 0 : undefined}
      role={scrolls ? "region" : undefined}
      aria-label={scrolls ? (props["aria-label"] ?? "Table") : undefined}
      className="relative w-full overflow-x-auto rounded-[inherit] outline-none focus-visible:ring-1 focus-visible:ring-ring focus-visible:ring-inset"
    >
      <table
        data-slot="table"
        className={cn("w-full caption-bottom text-sm", className)}
        {...props}
      />
    </div>
  )
}

function TableHeader({ className, ...props }: React.ComponentProps<"thead">) {
  return (
    <thead
      data-slot="table-header"
      className={cn("[&_tr]:border-b", className)}
      {...props}
    />
  )
}

function TableBody({ className, ...props }: React.ComponentProps<"tbody">) {
  return (
    <tbody
      data-slot="table-body"
      className={cn("[&_tr:last-child]:border-0", className)}
      {...props}
    />
  )
}

function TableFooter({ className, ...props }: React.ComponentProps<"tfoot">) {
  return (
    <tfoot
      data-slot="table-footer"
      className={cn(
        "border-t bg-muted/50 font-medium [&>tr]:last:border-b-0",
        className
      )}
      {...props}
    />
  )
}

function TableRow({ className, ...props }: React.ComponentProps<"tr">) {
  return (
    <tr
      data-slot="table-row"
      className={cn(
        "border-b transition-colors duration-fast ease-entrance hover:bg-muted/50 has-aria-expanded:bg-muted/50 data-[state=selected]:bg-muted",
        className
      )}
      {...props}
    />
  )
}

function TableHead({ className, ...props }: React.ComponentProps<"th">) {
  return (
    <th
      data-slot="table-head"
      className={cn(
        "h-(--control-md) px-3 text-left align-middle font-medium whitespace-nowrap text-foreground first:pl-4 last:pr-4 [&:has([role=checkbox])]:pr-0",
        className
      )}
      {...props}
    />
  )
}

function TableCell({ className, ...props }: React.ComponentProps<"td">) {
  return (
    <td
      data-slot="table-cell"
      className={cn(
        "px-3 py-(--row-py) align-middle whitespace-nowrap first:pl-4 last:pr-4 [&:has([role=checkbox])]:pr-0",
        className
      )}
      {...props}
    />
  )
}

function TableCaption({
  className,
  ...props
}: React.ComponentProps<"caption">) {
  return (
    <caption
      data-slot="table-caption"
      className={cn("mt-4 text-sm text-muted-foreground", className)}
      {...props}
    />
  )
}

export {
  Table,
  TableHeader,
  TableBody,
  TableFooter,
  TableHead,
  TableRow,
  TableCell,
  TableCaption,
}

"use client"

import * as React from "react"

/** True while the element's content is wider than the element (it scrolls sideways). */
export function useOverflowX<T extends HTMLElement>(ref: React.RefObject<T | null>) {
  const [overflow, setOverflow] = React.useState(false)
  React.useEffect(() => {
    const el = ref.current
    if (!el) return
    const check = () => setOverflow(el.scrollWidth > el.clientWidth + 1)
    check()
    const ro = new ResizeObserver(check)
    ro.observe(el)
    // Every child, and children added later: a new Kanban column widens the
    // content without resizing the element or its first child.
    const watch = () => {
      for (const child of Array.from(el.children)) ro.observe(child)
      check()
    }
    watch()
    const mo = new MutationObserver(watch)
    mo.observe(el, { childList: true })
    return () => {
      ro.disconnect()
      mo.disconnect()
    }
  }, [ref])
  return overflow
}

import type { CnFunction } from "cn"
import { createCn } from "cn/config"

/**
 * clsx + tailwind-merge, taught WunderUI's own theme utilities so they merge
 * in the right group: `text-label-sm` is a font size (not a text colour, which
 * dropped it next to `text-text-tertiary`), `bg-gradient-*` a background image
 * (not a colour that `bg-card` would remove), and the motion utilities
 * `ease-entrance …` and `duration-fast …` replace each other.
 */
export const cn: CnFunction = createCn({
  extend: {
    classGroups: {
      "font-size": [{ text: ["label-sm"] }],
      "bg-image": [
        {
          bg: [
            "gradient-primary",
            "gradient-indigo",
            "gradient-blue",
            "gradient-purple",
            "gradient-pink",
            "gradient-red",
            "gradient-orange",
            "gradient-yellow",
            "gradient-green",
            "gradient-alternative",
            "gradient-slate",
            "gradient-dark",
          ],
        },
      ],
      ease: [{ ease: ["entrance", "exit", "move", "overshoot", "spring"] }],
      duration: [{ duration: ["instant", "fast", "base", "slow", "deliberate", "ambient"] }],
    },
  },
})
